"""Dense-regime plan timing probe (dev only)."""
import importlib.util, itertools, json, random, sys, time
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
H = 8; kinds = 'DQT' + 'K'*5; tmpl = bytes([0,0,0xff]+[0]*5); pp = 3

def build(n, nn, plen, cap, bv, rng):
    nodes = ['n%d' % i for i in range(nn)]
    caps = {nd: cap for nd in nodes}
    flows=[]; offers={}; bens=[]
    for i in range(n):
        path = rng.sample(nodes, min(plen, nn))
        flows.append({'id':'f%d'%i,'path':path,'template':tmpl.hex(),'kinds':kinds})
        hdr = bytearray(H); hdr[1]=3; hdr[2]=200
        for j in range(3,H): hdr[j]=tmpl[j]
        offers['f%d'%i]=[{'header':hdr.hex(),'count':bv[i]}]
        bens.append(bv[i]*pp*len(path))
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':0,
            'pinned':[],'offers':offers}, bens

worst=(0,None); rows=0
for nn in (10,12,16,22,30,45):
  for plen in (7,9):
    for cap in (5,6,8,10,13,17):
      for mode in ('eq','near','rand','pow'):
        for seed in range(2):
            rng = random.Random(hash((nn,plen,cap,mode,seed))&0xffffff)
            n=22
            bv = ([7]*n if mode=='eq' else [100+i for i in range(n)] if mode=='near'
                  else [rng.randint(1,100) for _ in range(n)] if mode=='rand'
                  else [1<<rng.randint(0,20) for _ in range(n)])
            req,bens = build(n,nn,plen,cap,bv,rng)
            t0=time.time(); got=m.handle(json.loads(json.dumps(req))); dt=time.time()-t0
            rows+=1
            if 'error' in got: print('ERR',nn,plen,cap,mode); continue
            bmap=dict(zip([f['id'] for f in req['flows']],bens))
            assert sum(bmap[s] for s in got['selected'])==got['saved']
            fmap={f['id']:f for f in req['flows']}
            for nd,c in req['capacities'].items():
                assert sum(1 for s in got['selected'] if nd in fmap[s]['path'])<=c
            if dt>worst[0]: worst=(dt,(nn,plen,cap,mode,seed,len(got['selected'])))
            if dt>0.3: print('SLOW %.2f'%(dt), nn,plen,cap,mode,seed, flush=True)
print('rows=%d worst=%.3f %s' % (rows, worst[0], worst[1]), flush=True)
PYEOF
